//! Renders a validated [`VersionPalette`](super::model::VersionPalette) to the Rust
//! source `bedrock_vanilla_data` compiles.
//!
//! Every list on the model is already sorted (`model.rs`), so emission just walks it in
//! order -- the stable-ordering half of the determinism requirement is earned before this
//! module runs, not here.

use proc_macro2::TokenStream;
use quote::quote;

use super::diff::{BlockChange, PropertyChange, PropertyValueDelta, RenameChange, VersionDiff};
use super::model::{BlockSpec, PropertyKind, PropertySpec, VersionPalette};

/// The generated file's module name for one version, e.g. `v1_20_10` for `(1, 20, 10)`.
/// See `codegen::versioned_module_name`, shared with `codegen::biome::emit`.
pub fn module_name(game_version: (u8, u8, u8)) -> String {
    super::super::versioned_module_name("", game_version)
}

/// Renders one version's palette to a full source file (including the `#![doc]` file
/// header and the `use` it needs), ready to hand to `prettyplease`. The header text
/// itself is built by `codegen::generated_header`, shared with `codegen::biome::emit`.
pub fn render_version_file(palette: &VersionPalette) -> TokenStream {
    let tag = &palette.tag;
    let (major, minor, patch) = palette.game_version;

    let header = super::super::generated_header(
        tag,
        "metadata/vanilladata_modules/mojang-blocks.json",
        "xtask/src/codegen/palette",
    );

    let properties = palette.properties.iter().map(render_property_spec);
    let blocks = palette.blocks.iter().map(render_block_spec);

    quote! {
        #![doc = #header]

        use crate::palette::{BlockSpec, PropertyKind, PropertySpec, VersionPalette};

        pub static PALETTE: VersionPalette = VersionPalette {
            tag: #tag,
            game_version: (#major, #minor, #patch),
            properties: &[
                #(#properties),*
            ],
            blocks: &[
                #(#blocks),*
            ],
        };
    }
}

/// Renders the top-level `generated/mod.rs`: one `pub mod` per palette/diff/biome module
/// plus the `PALETTES`, `DIFFS`, and `BIOMES` registries. `palette_modules` is
/// oldest-version-first (the order the caller sorted [`VersionPalette`]s in -- see
/// `mod.rs`); `diff_modules` is one entry per adjacent pair in that same order, so
/// `DIFFS[i]` is always the diff from `PALETTES[i]` to `PALETTES[i + 1]`; `biome_modules`
/// is oldest-version-first among whichever pinned tags carry a biome dump with numeric
/// ids (`codegen::biome`'s own, independent ladder).
pub fn render_mod_file(
    palette_modules: &[String],
    diff_modules: &[String],
    biome_modules: &[String],
) -> TokenStream {
    let all_modules = palette_modules
        .iter()
        .chain(diff_modules)
        .chain(biome_modules);
    let mods = all_modules.map(|m| {
        let ident = syn::Ident::new(m, proc_macro2::Span::call_site());
        quote! { pub mod #ident; }
    });

    let palette_entries = palette_modules.iter().map(|m| {
        let ident = syn::Ident::new(m, proc_macro2::Span::call_site());
        quote! { #ident::PALETTE }
    });
    let diff_entries = diff_modules.iter().map(|m| {
        let ident = syn::Ident::new(m, proc_macro2::Span::call_site());
        quote! { #ident::DIFF }
    });
    let biome_entries = biome_modules.iter().map(|m| {
        let ident = syn::Ident::new(m, proc_macro2::Span::call_site());
        quote! { #ident::BIOMES }
    });

    quote! {
        //! Generated by `cargo xtask generate-palette`. Do not edit by hand.

        #(#mods)*

        /// Every generated per-version palette, oldest game version first.
        pub static PALETTES: &[crate::palette::VersionPalette] = &[
            #(#palette_entries),*
        ];

        /// Every generated adjacent-pair diff, oldest-to-newest -- `DIFFS[i]` is the diff
        /// from `PALETTES[i]` to `PALETTES[i + 1]`.
        pub static DIFFS: &[crate::diff::VersionDiff] = &[
            #(#diff_entries),*
        ];

        /// Every generated per-version biome id->name table, oldest game version first
        /// among whichever pinned tags carry a numeric-id biome dump.
        pub static BIOMES: &[crate::biome::VersionBiomes] = &[
            #(#biome_entries),*
        ];
    }
}

/// The generated diff file's module name for one adjacent pair, e.g.
/// `diff_v1_20_10_to_v1_21_0` for `(1, 20, 10) -> (1, 21, 0)`.
pub fn diff_module_name(from: (u8, u8, u8), to: (u8, u8, u8)) -> String {
    let (fmaj, fmin, fpat) = from;
    let (tmaj, tmin, tpat) = to;
    format!("diff_v{fmaj}_{fmin}_{fpat}_to_v{tmaj}_{tmin}_{tpat}")
}

/// Renders one adjacent-pair diff to a full source file. See
/// [`render_version_file`]'s doc comment for why the header is a `#![doc = ...]`
/// attribute rather than a `//!` comment.
pub fn render_diff_file(diff: &VersionDiff) -> TokenStream {
    let from_tag = &diff.from_tag;
    let to_tag = &diff.to_tag;
    let (fmaj, fmin, fpat) = diff.from_version;
    let (tmaj, tmin, tpat) = diff.to_version;

    let header = format!(
        " Generated by `cargo xtask generate-palette`, diffing the `{from_tag}` and \
          `{to_tag}` releases of `Mojang/bedrock-samples` (both path \
          `metadata/vanilladata_modules/mojang-blocks.json`), merged against \
          `xtask/dumps/bedrock-samples/renames.json`. Do not edit by hand -- edit the \
          generator (`xtask/src/codegen/palette/diff.rs`) or the pinned inputs instead, \
          and regenerate."
    );

    let blocks_added = &diff.blocks_added;
    let blocks_removed = &diff.blocks_removed;
    let renames = diff.renames.iter().map(render_rename_change);
    let block_changes = diff.block_changes.iter().map(render_block_change);
    let property_changes = diff.property_changes.iter().map(render_property_change);

    quote! {
        #![doc = #header]

        pub static DIFF: crate::diff::VersionDiff = crate::diff::VersionDiff {
            from_tag: #from_tag,
            to_tag: #to_tag,
            from_version: (#fmaj, #fmin, #fpat),
            to_version: (#tmaj, #tmin, #tpat),
            blocks_added: &[#(#blocks_added),*],
            blocks_removed: &[#(#blocks_removed),*],
            renames: &[
                #(#renames),*
            ],
            block_changes: &[
                #(#block_changes),*
            ],
            property_changes: &[
                #(#property_changes),*
            ],
        };
    }
}

fn render_rename_change(r: &RenameChange) -> TokenStream {
    let from = &r.from;
    let to = &r.to;
    quote! { crate::diff::RenameChange { from: #from, to: #to } }
}

fn render_block_change(c: &BlockChange) -> TokenStream {
    let block = &c.block;
    let added = &c.properties_added;
    let removed = &c.properties_removed;
    quote! {
        crate::diff::BlockChange {
            block: #block,
            properties_added: &[#(#added),*],
            properties_removed: &[#(#removed),*],
        }
    }
}

fn render_property_change(c: &PropertyChange) -> TokenStream {
    let property = &c.property;
    let delta = match &c.delta {
        PropertyValueDelta::KindChanged { from, to } => {
            quote! { crate::diff::PropertyValueDelta::KindChanged { from: #from, to: #to } }
        }
        PropertyValueDelta::Int { added, removed } => {
            quote! { crate::diff::PropertyValueDelta::Int { added: &[#(#added),*], removed: &[#(#removed),*] } }
        }
        PropertyValueDelta::Str { added, removed } => {
            quote! { crate::diff::PropertyValueDelta::Str { added: &[#(#added),*], removed: &[#(#removed),*] } }
        }
    };
    quote! {
        crate::diff::PropertyChange {
            property: #property,
            delta: #delta,
        }
    }
}

fn render_property_spec(spec: &PropertySpec) -> TokenStream {
    let name = &spec.name;
    let kind = match &spec.kind {
        PropertyKind::Bool => quote! { PropertyKind::Bool },
        PropertyKind::Int(values) => quote! { PropertyKind::Int(&[#(#values),*]) },
        PropertyKind::Str(values) => quote! { PropertyKind::Str(&[#(#values),*]) },
    };
    quote! {
        PropertySpec {
            name: #name,
            kind: #kind,
        }
    }
}

fn render_block_spec(spec: &BlockSpec) -> TokenStream {
    let name = &spec.name;
    let properties = &spec.properties;
    quote! {
        BlockSpec {
            name: #name,
            properties: &[#(#properties),*],
        }
    }
}
